mapper.select:
SELECT j.*,
       (SELECT COUNT(*) FROM rec_application a WHERE a.job_position_id = j.id AND a.deleted = 0) AS application_count
FROM rec_job_position j

    j.deleted = 0

        AND j.title LIKE CONCAT('%', #{title}, '%')


        AND j.department_id = #{departmentId}


        AND j.status = #{status}


        AND j.position_type = #{type}


        AND j.work_location LIKE CONCAT('%', #{location}, '%')


        AND j.publish_time >= #{startDate}


        AND j.publish_time <= #{endDate}


ORDER BY j.create_time DESC
